const express = require("express");
const session = require("express-session");
const bcrypt = require("bcryptjs");
const fs = require("fs");

const app = express();
const PORT = process.env.PORT || 3000;
const DB_FILE = process.env.DATA_FILE || "results.json";

app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(session({
  secret: process.env.SESSION_SECRET || "change-this-elpc-secret",
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, sameSite: "lax" }
}));

function loadDB() {
  if (!fs.existsSync(DB_FILE)) {
    const db = {
      admin: { username: "admin", passwordHash: bcrypt.hashSync("admin123", 10) },
      students: []
    };
    fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2));
    return db;
  }
  return JSON.parse(fs.readFileSync(DB_FILE, "utf8"));
}
function saveDB(db) { fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2)); }
function auth(req, res, next) {
  if (req.session.admin) return next();
  res.status(401).json({ error: "Unauthorized" });
}

const LOGO = Buffer.from("", "base64");

const HTML = `<!doctype html>
<html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ELPC Student Results</title>
<style>
*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f4f7fb;color:#172033}
header{background:#101828;color:#fff;padding:12px 6%;display:flex;justify-content:space-between;align-items:center}
.brand{display:flex;align-items:center;gap:10px}.brand img{width:48px;height:48px;object-fit:contain;border-radius:50%}
.brand b{font-size:25px;color:#55d6be}.brand span{display:block;font-size:13px;opacity:.8}
button{border:0;border-radius:8px;padding:11px 16px;background:#1769e0;color:#fff;font-weight:700}
main{max-width:1100px;margin:auto;padding:30px 16px}.card{background:#fff;border-radius:18px;padding:30px;box-shadow:0 8px 30px #0001}
.hero{text-align:center}.hero h1{font-size:36px;margin:5px 0}.search{display:flex;gap:10px;max-width:600px;margin:22px auto}
input{width:100%;padding:12px;border:1px solid #ccd4df;border-radius:8px;font-size:15px}
.hidden{display:none}.admin{margin-top:24px}.panel{margin-top:16px}.form{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:18px 0}
.table{overflow:auto}table{width:100%;border-collapse:collapse;min-width:850px}th,td{padding:9px;border-bottom:1px solid #e5e7eb;text-align:left}
.result{max-width:800px;margin:20px auto;text-align:left;border:1px solid #e5e7eb;border-radius:12px;padding:18px}
.marks{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.mark{background:#f8fafc;padding:10px;border-radius:8px}
@media(max-width:700px){.hero h1{font-size:28px}.search{flex-direction:column}.form{grid-template-columns:1fr 1fr}.marks{grid-template-columns:1fr 1fr}}
</style></head>
<body>
<header><div class="brand"><img src="/logo.png"><div><b>ELPC</b><span>Easy Learn Physics Classes</span></div></div>
<button onclick="toggleAdmin()">Admin</button></header>
<main><section class="card hero"><h1>Student Result Portal</h1><p>Enter your Roll Number to view your result.</p>
<div class="search"><input id="roll" placeholder="Enter Roll Number"><button onclick="findResult()">View Result</button></div><div id="result"></div></section>
<section id="admin" class="admin hidden"><div id="login" class="card panel"><h2>Admin Login</h2>
<input id="user" placeholder="Admin ID" value="admin"><input id="pass" type="password" placeholder="Password"><br><br><button onclick="login()">Login</button>
<p>Default: admin / admin123</p></div>
<div id="dashboard" class="card panel hidden"><h2>Admin Dashboard</h2>
<button onclick="logout()">Logout</button> <button onclick="changePassword()">Change Password</button>
<div class="form"><input id="sid" type="hidden"><input id="sroll" placeholder="Roll No"><input id="sname" placeholder="Student Name">
<input id="physics" type="number" placeholder="Physics"><input id="chemistry" type="number" placeholder="Chemistry">
<input id="math" type="number" placeholder="Math"><input id="english" type="number" placeholder="English">
<input id="hindi" type="number" placeholder="Hindi"><button onclick="saveStudent()">Save Student</button><button onclick="clearForm()">Clear</button></div>
<div class="table"><table><thead><tr><th>Roll</th><th>Name</th><th>Physics</th><th>Chemistry</th><th>Math</th><th>English</th><th>Hindi</th><th>Action</th></tr></thead>
<tbody id="students"></tbody></table></div></div></section></main>
<script>
const $=id=>document.getElementById(id);
function toggleAdmin(){$("admin").classList.toggle("hidden");$("admin").scrollIntoView({behavior:"smooth"})}
async function findResult(){const r=$("roll").value.trim();if(!r)return;const x=await fetch("/api/result/"+encodeURIComponent(r));const d=await x.json();$("result").innerHTML=x.ok?resultHTML(d):'<div class="result">❌ '+d.error+"</div>"}
function resultHTML(d){return '<div class="result"><h2>'+esc(d.name)+'</h2><p><b>Roll No:</b> '+esc(d.roll)+'</p><div class="marks">'+
["physics","chemistry","math","english","hindi"].map(k=>'<div class="mark">'+k[0].toUpperCase()+k.slice(1)+'<br><b>'+d[k]+'</b></div>').join("")+
'</div><h3>Total: '+d.total+' / 500 | Percentage: '+d.percentage+'% | '+d.status+'</h3></div>'}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
async function login(){const x=await fetch("/api/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:$("user").value,password:$("pass").value})});const d=await x.json();if(!x.ok)return alert(d.error);$("login").classList.add("hidden");$("dashboard").classList.remove("hidden");loadStudents()}
async function loadStudents(){const x=await fetch("/api/students");if(!x.ok)return;const a=await x.json();$("students").innerHTML=a.map(s=>'<tr><td>'+esc(s.roll)+'</td><td>'+esc(s.name)+'</td><td>'+s.physics+'</td><td>'+s.chemistry+'</td><td>'+s.math+'</td><td>'+s.english+'</td><td>'+s.hindi+'</td><td><button onclick="editStudent('+s.id+')">Edit</button> <button onclick="deleteStudent('+s.id+')">Delete</button></td></tr>').join("")}
async function editStudent(id){const x=await fetch("/api/students");const a=await x.json();const s=a.find(v=>v.id===id);if(!s)return;for(const k of ["roll","name","physics","chemistry","math","english","hindi"])$("s"+k).value=s[k];$("sid").value=s.id}
function clearForm(){["sid","sroll","sname","physics","chemistry","math","english","hindi"].forEach(i=>$(i).value="")}
async function saveStudent(){const body={roll:$("sroll").value.trim(),name:$("sname").value.trim(),physics:$("physics").value,chemistry:$("chemistry").value,math:$("math").value,english:$("english").value,hindi:$("hindi").value};if(!body.roll||!body.name)return alert("Roll number and name required");const id=$("sid").value;const x=await fetch(id?"/api/students/"+id:"/api/students",{method:id?"PUT":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await x.json();if(!x.ok)return alert(d.error);clearForm();loadStudents()}
async function deleteStudent(id){if(!confirm("Delete this student?"))return;await fetch("/api/students/"+id,{method:"DELETE"});loadStudents()}
async function logout(){await fetch("/api/logout",{method:"POST"});location.reload()}
async function changePassword(){const p=prompt("New password (minimum 6 characters):");if(!p)return;const x=await fetch("/api/change-password",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({password:p})});const d=await x.json();alert(x.ok?"Password changed":d.error)}
</script></body></html>`;

app.get("/", (req,res)=>res.type("html").send(HTML));
app.get("/logo.png",(req,res)=>res.type("png").send(LOGO));

app.get("/api/result/:roll",(req,res)=>{
  const db=loadDB(), s=db.students.find(v=>v.roll===req.params.roll.trim());
  if(!s) return res.status(404).json({error:"Result not found"});
  const total=Number(s.physics)+Number(s.chemistry)+Number(s.math)+Number(s.english)+Number(s.hindi);
  const percentage=total/5;
  res.json({...s,total,percentage:percentage.toFixed(2),status:percentage>=33?"PASS":"FAIL"});
});
app.post("/api/login",(req,res)=>{
  const db=loadDB(), a=db.admin;
  if(req.body.username!==a.username || !bcrypt.compareSync(req.body.password,a.passwordHash))
    return res.status(401).json({error:"Invalid ID or password"});
  req.session.admin={username:a.username}; res.json({ok:true});
});
app.post("/api/logout",auth,(req,res)=>req.session.destroy(()=>res.json({ok:true})));
app.get("/api/students",auth,(req,res)=>res.json(loadDB().students));
app.post("/api/students",auth,(req,res)=>{
  const db=loadDB(), x=req.body;
  if(db.students.some(s=>s.roll===String(x.roll).trim())) return res.status(400).json({error:"Roll number already exists"});
  const id=db.students.length?Math.max(...db.students.map(s=>s.id))+1:1;
  db.students.push({id,roll:String(x.roll).trim(),name:String(x.name).trim(),physics:+x.physics||0,chemistry:+x.chemistry||0,math:+x.math||0,english:+x.english||0,hindi:+x.hindi||0});
  saveDB(db); res.json({ok:true,id});
});
app.put("/api/students/:id",auth,(req,res)=>{
  const db=loadDB(), s=db.students.find(v=>v.id===Number(req.params.id));
  if(!s)return res.status(404).json({error:"Student not found"});
  Object.assign(s,{roll:String(req.body.roll).trim(),name:String(req.body.name).trim(),physics:+req.body.physics||0,chemistry:+req.body.chemistry||0,math:+req.body.math||0,english:+req.body.english||0,hindi:+req.body.hindi||0});
  saveDB(db);res.json({ok:true});
});
app.delete("/api/students/:id",auth,(req,res)=>{const db=loadDB();db.students=db.students.filter(s=>s.id!==Number(req.params.id));saveDB(db);res.json({ok:true})});
app.post("/api/change-password",auth,(req,res)=>{
  if(!req.body.password || req.body.password.length<6)return res.status(400).json({error:"Password must be at least 6 characters"});
  const db=loadDB();db.admin.passwordHash=bcrypt.hashSync(req.body.password,10);saveDB(db);res.json({ok:true});
});

app.listen(PORT,()=>console.log("ELPC Results Portal running on port "+PORT));
